from build import save
rows=[
(451,['萧七战七胜，糖果书生各实战败。炎神用高频小火球与刻薄激怒赢苍冥，苍冥整理心态赴赌。萧开局亮影子战士与比蒙，双突击链耗完苍冥逃命逼冰封，公众首知底牌。'],['藏实力对刀剑的险胜被公众重估，苍冥视频研究遗漏关键技能。'],['炎神言语段主体写苍冥是源误名。'],28048,28106),
(452,['萧隐等冰封结束使苍冥乱轰耗蓝再5秒杀。赌约有主脑强制力，拒双倍补偿。炎神亮冰火双法后因影子/暗影克制认输。九胜冠军，炎神2苍冥3刀剑4糖果5猴6橘7书8小刀9柠10。萧赵2v2用全力夺冠，死神与黎治组只提造成威胁。'],['1v1与2v2实际获冠，非资格；赌约尚待退场执行。'],[],28107,28166),
(453,['风神三人3v3、刺刀队5v5、风野团实际冠，后者装备碾压。萧高位神器圣者礼赞13件全技能、全属性+300%等，前三绑定；赵中位神器套，萧二冠改50次500%3分钟天之圣水。风野诅咒甲群传5000，被主角认任务准备。退场主脑强制收苍冥全部装备，其永远消失。旧装备会内处理，二人清闲风野筹五千。'],['赌约已执行；新的奖品能力转为神战准备。'],[],28167,28223),
(454,['茶馆私密亲昵被流星入侵中断，及时跳窗救，茶馆毁。资料片末日之刃开、黑暗总攻，两联盟暂结盟，新图乌服诺斯公开，二转需新击十单位旧杀不算。克文图斯禁咒清数十万仍增援不断，黑龙驹6级会飞载二人上前线。'],['敌已侵城，NPC胜一波不等于战毕；主线进入共同抵抗。'],[],28224,28291),
(455,['骷髅阵缝隙安法群刷，赵神装三万伤六万暴。二人十杀实际二转恶魔猎人+30%攻，再升61/62。比蒙53皮甲硬化+60%血+30%防追成长。赵新禁咒耗全蓝招30余同等强化水元素15分，先输出到期自爆；萧筛全贼技及幽影150%永久隐，需16级探隐、只单目标、不可控待明。'],['二转锁解除；高手方法可学而装差限制他人速度。'],[],28292,28347),
(456,['影子70%，风野五千队任务五天期限；风野报告天使赛萧翎双冠其团全余冠，两萧旧交平手均有藏。萧接单人恩泽斯期盼，赵去五千团；五天后赵73萧72比蒙70血20万，影子90幽影180。五千全60二转，刺刀和解同队。艾斐尔指单人开光暗之门到神境、问空间转换暂不释。'],['双任务分路，战争五天未结束敌70进90；主神力量尚未获得。'],[],28348,28415),
(457,['分影与本体分引两个80超阶执金。幽影不可控只伤害不能战术；800万血执金全治阻放血，改魔力流逝/蒸发50%消蓝再磨，15分与13分各杀，比蒙被轰杀仍成功。中位神斧剑上交易平台引市价，准备进门。'],['以资源瓶颈替单增输出解决无限治疗，光门尚未开。'],['魔力流逝写每秒掉血但文意掉蓝；侦察5万血亦与800万血/蓝说法冲突。'],28416,28461),
(458,['门前推吸力挡，凹槽放空间转换解封开的是光门；本器五人任点非战传、战可随机跳。进神境为双星小卫星之一，见天使五千队，联盟结盟不可攻击。天狂雷焰萧翎到场、龙焰胜圣火第一。沃克确神灵，沃尔希德许完任下位神格和NPC发任务赐福权。'],['空间转换关联钥匙回收，奖承诺未得。'],[],28462,28522),
(459,['萧实际接开暗门毁本命任务，神引主神临力；密室观万人争领导。萧知己单体与萧翎群法团效不同。风野协调骑兵破阵，雷焰六强团与一千火法二转12炎爆反击，风野剩不足2000对3600。'],['临时主神非永久成神；团战尚未在本单元结束。'],[],28523,28578),
(460,['风野实际认输雷焰领万人，坦然使会众释怀；神引万人至少下位神战肉身、萧单走本命。空间转换另开暗门，旁白说明光暗同门空间错位两面，系统公告。萧返荒漠主神碾低怪，原方盒已不见仍猜本命；百半神杀，100超阶护盾拖到血祭唤雕像。'],['领导权决出、门开；方盒没被找出或明确毁掉。'],[],28579,28637),
(461,['雕像现沃顿分身主神3000万血，金甲近无敌；殿被毁埋，主角被打至12%靠主神快复和自接骨，回忆只断手骨与流氓非心口刀伤。另一边万人付3000余死后，赵200水元素爆、萧翎火龙567398终杀沃顿肉身，魂逸。'],['荒漠薄守误判纠正；团战目标肉身死，分身仍存。'],[],28638,28694),
(462,['肉身死使分身甲黯萧能伤，主神时间停顿接龙翔偶得876万不可重做；魂来融合，萧破盾抓心口白光格杀。沃顿记忆毁恩泽斯为让黑太阳乌星得阳造生，文本映新星殖民/票价作立场伦理解释。系统任务完成得沃尔希德残留神格，临力退永久下位神，反攻图开。主角化名盗神肖恩假NPC给女贼十环杂务，赵喊萧破身份、女仍做。'],['终战任务获系统完成；本命物实体与旧方盒未再指认，不能补造毁盒。'],[],28695,28774),
(463,['明日启程新星前萧翎邀末战，萧改夜为昼求不占贼优势；赵有失落仍同意。比蒙76血37万、影战神160%、幽魅刺客与萧翎傀儡群战，萧下位神对萧翎凡体。萧夹击先杀萧翎，延时末日审判压到12%，跳台余11%生还；半小时萧翎起搏复坦认输，矮人酒友笑。机场三人告同学、燕远望送别独等，萧不复合；三人登机飞行器实际起飞。'],['最高末战明确萧胜；赴新星从计划至实际离地，未写抵达。'],['t望台/萧御持杖、末法攻击名误写保留；不并双萧。'],28775,28897),
]
d={
'worldbuilding':[['圣者礼赞13件高位神器全贼技、全属+300%、负面免和魔免60物免75规避60；竞技前三绑定，萧第二冠奖改天之圣水50次500%3分，非旧圣言圣水。','fact',[453,28175,28186]],['资料片开启才计二转十杀，旧乌星击杀不算；竞技神装让十杀容易不代表普通玩家同样轻松。','fact',[454,28252,28259],[455,28309,28313]],['影子可控有战术作用；幽影高属性却不可控且单目标、目标亡即消，二者不同功能。','fact',[455,28343,28345],[457,28428,28429],[457,28457,28457]],['空间转换既任点携五非战传又战中随机跳，是双面同门错位的钥匙；阶段只开光与后开暗分步骤。','fact',[458,28466,28475],[460,28594,28601]],['主神是引导临时力量，任务后只下位神；下位神权限包括发布任务、永久赐福，结尾肖恩杂务实际展示。','fact',[458,28516,28520],[459,28525,28532],[462,28736,28771]]],
'characters':[['萧对苍冥拒悔改双偿并执行毁前程，强硬与对刀剑炎神的友善依对象而分；不可将其等同普遍宽容英雄。','fact',[452,28143,28149],[453,28194,28194]],['赵用群魔刷怪、自主试水元素先误耗全蓝再找末时自爆策略，关键神战亦贡献200元素；她的能力不只陪衬冠军。','fact',[455,28320,28337],[461,28683,28688]],['风野输雷焰仍坦认强中有强，把会众从耻感转回游戏常态；局部失败不取消组织领导。','fact',[460,28580,28586]],['末战两萧求无保留与痛快，萧改昼不占优势，萧翎起搏复坦认输后喝酒；对抗终为同级友谊。','fact',[463,28779,28799],[463,28870,28882]]],
'plot':[['竞技奖品不是终点，群传5000先显多余能力、后接五千团任务；单人全神器与钥匙另导隐秘目标。','inference',[453,28188,28202],[456,28352,28379],[459,28527,28532]],['肉身与分身两个战场有因果耦合：万人杀肉身才让主角可破甲，最终魂归制造短促胸口机会，不能说主角独自完成全神战。','fact',[461,28680,28692],[462,28697,28704],[462,28719,28736]],['空间转换由传送器转钥匙，沃克由问号服务者转神灵，本段完成身份功能回收；方盒只不见未单独指认为本命。','fact',[458,28466,28475],[458,28501,28505],[460,28624,28625]],['游戏终极对决明确结果后落到同学离别和实际起飞，胜利闭环与生活迁移闭环并行；未继续写新星抵达后人生。','inference',[463,28863,28882],[463,28883,28894]]],
'style':[['后期范围魔法、30万级伤害、数百水元素等奇观明显放大，同时用2108、11%之类剩余值保留险胜感。','inference',[461,28683,28692],[462,28715,28718],[463,28865,28868]],['学全技能后主角主动分类剔重复，解释“更多”如何被使用；后资源型执金题用出血和消蓝两套模型对照。','inference',[455,28340,28345],[457,28436,28450]],['462把沃顿生平与现实问题集中旁白议论，思想解释量超过情节现场，虽能重释对立，也压缩本命实体处置细节。','inference',[462,28727,28740]],['453–454私密身体描写有物化和默认顺从叙事，研究仅非露骨记录其关系阶段，不抽成情感范本。','inference',[453,28212,28221],[454,28225,28238]]],
'narrative':[['末段会聚两部人物，依主语与阵营、职业区分萧御/萧翎；偶发持杖等误称不合并其身份。','fact',[456,28364,28371],[458,28488,28495],[463,28839,28841]],['万人战由萧御水晶旁观，既能写风野全阵也保留主角不在场；随后双战场交替让观众知道甲弱原因。','inference',[459,28535,28542],[460,28588,28590],[461,28679,28692],[462,28697,28704]],['政府解释只是主角/叙述者“或许”，游戏阵营影现实移民界线是文本解释，不是外部社会事实或作者已证幕后委托。','fact',[462,28731,28735]],['463“第一次全力”与已来往次数用人物说法记第三次；最终萧仍提下位神属性优势，不因白昼公平意愿掩平等级差。','fact',[463,28796,28812],[463,28867,28868]]],
'dialogue':[['炎神主动认输先亮冰法是有能力仍评估相克，不单纯怕输；让省略的决赛依知识判断成立。','inference',[452,28150,28157]],['沃尔希德奖励谈话先让玩家成神惊讶，再解释NPC权能，后肖恩恶作剧把抽象权限转可见动作。','inference',[458,28516,28520],[462,28744,28771]],['末战后“我输了”与坏酒玩笑把竞争的严肃承诺收成平等友谊，结果明确而无需辱败者。','inference',[463,28873,28882]]],
'pacing':[['1v1余轮与2v2团赛快速报结果，主要空间给苍冥心理败局；先前死神独立铺陈到对战只一句险胜，兑现粒度不均。','inference',[451,28057,28076],[452,28108,28164],[453,28168,28170]],['五天练级同时推进影子技能、五千人门槛与攻城升级，让短时跃升被战事压力包住；但财富与等级增长极快。','inference',[456,28380,28391]],['主神阶段短时数值跃升绕过原技能细节，紧接最终PK又恢复连控和技能互换，结束保本书竞技卖点。','inference',[460,28619,28623],[461,28672,28679],[463,28820,28868]],['世界危机完成后先盗神喜剧放松，再末战收竞技遗愿、现实告别关门，三段尾声各换一种压力。','inference',[462,28741,28772],[463,28776,28799],[463,28883,28894]]],
'themes':[['沃顿为造生命欲毁另一星，把受害者需求与加害行为绑一起；文本说双方无错属立场论，但不能由此免除殖民灭族和侵略责任。','inference',[462,28731,28735]],['平民移民票价与国家资源问题被结局主动映照，早期生计到末期买票离开有现实社会框架，而政策辩护主要是叙述结论非多方辩论。','inference',[462,28734,28735],[463,28883,28894]],['个人化神并未关掉普通玩家游戏，他们继续组队探图；主角成为别人任务入口，强者退休后世界仍可运行。','inference',[462,28738,28771]],['燕独自承诺等到老与主角不再回头并存，结尾未给她独立新生活；这是感情收束局限，不能记作复合伏笔已必将兑现。','inference',[463,28889,28892]]],
'continuity':[['4521v1冠军九胜含认输，453赌约实际执行；事前仓库锁定与事后收装备不可混为一步。','fact',[452,28160,28164],[453,28194,28194]],['462系统任务完成，但未单独写毁方盒或展示本命骷髅形体；主角460仍猜方盒且其不见，须区分任务终结与物件解释缺口。','fact',[460,28624,28625],[462,28727,28737]],['458空间转换战随机可用不能推广为任点战传；459临时主神、462永久下位神不是同阶，463萧翎未成神。','fact',[458,28473,28474],[459,28530,28535],[462,28736,28737],[463,28812,28812]],['457侦察“五万血量”与八百万血量及后魔法叙述冲突，“魔力流逝耗血”与消蓝解法冲突；463持杖萧御、末法无躲处萧翎均与动作链相悖，保源误不补新人。','fact',[457,28436,28447],[463,28839,28841],[463,28865,28868]],['416凤凰末次被收，之后422起搏、463对手起搏，正文未再交代萧最后羽使用；没有出现不等同确定库存或弃线。','fact',[416,25570,25576],[422,26000,26003],[463,28870,28873]]],
}
